INSERT INTO category_content (category_slug, section_order, subheading, paragraphs, created_at, updated_at) VALUES
('miscellaneous-tech', 1, 'Mens Sport Watches: Durable and Functional', '["Our mens sport watches are designed to withstand active lifestyles while providing precise timekeeping. These watches feature robust materials, water resistance, and multiple functions such as stopwatches, alarms, and backlit displays. Perfect for athletes, outdoor enthusiasts, and those who prefer a rugged style, mens sport watches offer both practicality and performance. With modern designs and ergonomic features, they ensure comfort during prolonged wear while keeping you on schedule.","Whether you are training, hiking, or engaging in daily activities, a mens sport watch delivers reliability and durability, making it an essential accessory for an active lifestyle."]', unixepoch(), unixepoch()),
('miscellaneous-tech', 2, 'Womens Analogue Watches: Elegant Timekeeping', '["Our womens analogue watches provide a classic and sophisticated approach to timekeeping. Combining elegant design with reliable mechanics, these watches are suitable for work, social events, or casual wear. Each watch features clear dials, adjustable straps, and quality materials that ensure both comfort and longevity. Womens analogue watches allow you to express personal style while maintaining accurate timekeeping.","From sleek and minimalist designs to decorative and luxurious styles, these analogue watches cater to diverse tastes, making them a versatile accessory for every woman''s collection."]', unixepoch(), unixepoch()),
('miscellaneous-tech', 3, 'Quartz Watches: Precision and Reliability', '["Quartz watches offer highly accurate timekeeping powered by reliable quartz movements. Available for both men and women, these watches combine efficiency with stylish designs, making them perfect for everyday use or professional settings. Quartz watches require minimal maintenance and are known for their consistency and durability. At Rouge Technologies, our quartz watch selection ensures that you can enjoy precision timekeeping without sacrificing style or quality.","Whether you are looking for a reliable mens sport watch, a stylish womens analogue watch, or a precise quartz watch, Rouge Technologies provides high-quality options that suit all lifestyles and preferences. Explore our collection to find the perfect watch that balances performance, design, and durability."]', unixepoch(), unixepoch());
